SourceCode.Declaration:
/// <summary>
/// Sample batch job.
/// </summary>
[SysObsolete('Use MyNewBatchJob', false)]
class MyBatchJob extends RunBaseBatch {
CustAccount accountNum;
#define.CurrentVersion(1)
}

Method.Source:
public void run() {
CustTable custTable;
ttsbegin;
while select forupdate custTable
    where custTable.AccountNum == accountNum
       && custTable.Blocked == CustVendorBlocked::No {
custTable.CreditMax=1000;
custTable.update();
}
ttscommit;
switch(custTable.Blocked){
case CustVendorBlocked::All:
warning("@SYS12345");
break;
default:
info(strFmt("%1 done", accountNum));
}
}
